      SUBROUTINE AGENDR(LOC)CC     THE DECK CONTAINS MISALIGNMENTS REFERRED TO SINGLE MAGNETSC     CHECK TO SEE IF THE PRESENT MAGNET IS ONE SO REFERENCEDC     IF IT IS, LOOP THROUGH POSSIBLE MISALIGNMENT SPECIFICATIONSC      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM31B.CIN'C      IF (LOC .EQ. 2) GO TO 50      IF (NMISRB .EQ. 0) GO TO 100      NMARK = NUM      NUM = NMISRB - 1      NDIFM = NDIF      NDIF = 1      ALGR = .TRUE.      GO TO 100CC     TRANSFER BACK TO MARKERC   50 NUM = NMARK      NDIF = NDIFM      ALGR = .FALSE.C  100 RETURN      END